import {activeRefProof,nativePolicyResult} from './ref-reader.mjs';
import {RISK_POLICY} from './risk-rules.mjs';
import {choices,comparison,policySignals,composePolicy,exampleGame} from './decision-lab.mjs';
import {verifyCircuit} from './tapeout.mjs';
const panels=new Map(),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'$'+Math.round(n).toLocaleString('en-US');
const t=(lang,a,b)=>lang==='vi'?a:b;
const choiceName=(a,l)=>({buy:t(l,'Đầu tư','Invest'),skip:t(l,'Giữ tiền / bỏ qua','Keep cash / pass'),spend:t(l,'Chi tiêu','Spend'),hold:t(l,'Không điều chỉnh','No adjustment'),reserve:t(l,'Chuyển $500 vào dự phòng','Move $500 to reserve'),release:t(l,'Rút $500 dự phòng','Release $500 reserve'),invest:t(l,'Đầu tư $1.000','Invest $1,000'),sell:t(l,'Bán tối đa $1.000','Sell up to $1,000')})[a]||a;
export function timelineSVG(actual,alternative,l){
 const all=[...actual,...alternative],max=Math.max(1,...all.map(x=>x.liquid)),min=Math.min(0,...all.map(x=>x.liquid)),x=m=>45+m/12*650,y=v=>180-(v-min)/(max-min)*145,path=rows=>rows.map((p,i)=>(i?'L':'M')+x(p.month).toFixed(1)+','+y(p.liquid).toFixed(1)).join(' ');
 return `<svg class="lab-chart" viewBox="0 0 740 225" role="img" aria-label="${t(l,'Tiền mặt cộng dự phòng theo tháng; bảng số bên dưới chứa dữ liệu đầy đủ.','Cash plus reserve by month; the table below contains the full values.')}"><line x1="45" y1="180" x2="700" y2="180" stroke="#a9bdb0"/><text x="8" y="25">${money(max)}</text><text x="8" y="180">${money(min)}</text>${[0,3,6,9,12].map(m=>`<text x="${x(m)}" y="205">${m}</text>`).join('')}<path d="${path(actual)}" fill="none" stroke="#005d4b" stroke-width="3"/><path d="${path(alternative)}" fill="none" stroke="#c87732" stroke-width="3" stroke-dasharray="7 4"/>${actual.map(p=>`<circle cx="${x(p.month)}" cy="${y(p.liquid)}" r="3" fill="#005d4b"><title>${t(l,'Gốc','Original')} · ${p.month}: ${money(p.liquid)}</title></circle>`).join('')}${alternative.map(p=>`<circle cx="${x(p.month)}" cy="${y(p.liquid)}" r="3" fill="#c87732"><title>${t(l,'Thử lại','What if')} · ${p.month}: ${money(p.liquid)}</title></circle>`).join('')}</svg>`;
}
function signalHTML(s,l){const r=policySignals(s),m=r.model;return `<div class="lab-signals">${[[t(l,'R · Dự phòng ≥ 1 tháng','R · Reserve ≥ 1 month'),r.reserve,m.reserveMonths.toFixed(1)+' '+t(l,'tháng','months')],[t(l,'C · Đủ nghĩa vụ tháng tới','C · Next obligations covered'),r.coverage,money(m.after)+' '+t(l,'còn sau thu–chi đã biết','after known income/costs')],[t(l,'D · Trả góp ≤ 30% thu nhập','D · Installments ≤ 30% of income'),r.installments,money(m.installments)+' / '+money(m.income)]].map(([a,b,c])=>`<div class="${b?'pass':'caution'}"><strong>${a}</strong><b>${b?1:0}</b><small>${c}</small></div>`).join('')}</div>`;}
function compact(s,l){const g=s.gate;return `<p>${t(l,'Cổng dừng hiện có','Existing stop gate')}: IN0=${g.IN0} · IN1=${g.IN1} → OUT0=${g.OUT0}. ${g.OUT0===0?t(l,'DỪNG đầu tư mới theo quy tắc hiện tại.','STOP new investments under the existing rule.'):t(l,'Điều kiện dừng này chưa kích hoạt; không có nghĩa khoản đầu tư an toàn.','This stop condition is inactive; this does not mean an investment is safe.')}</p>`;}
function policyCopy(l){return `<p class="lab-fine">${t(l,'Các ngưỡng 1 tháng / 30% là quy tắc minh họa do Money Lab đặt, không phải chuẩn bảo đảm an toàn. Số tiền và điều kiện đầu vào do game tính. Phần ghép quy tắc nằm ngoài blockchain, dùng bảng chân trị thực tế của mạch #48; chưa triển khai mạch mới. Không đổi điểm, HUB hoặc quyết toán.','The 1-month / 30% thresholds are illustrative Money Lab rules, not safety standards. The game calculates financial inputs. Policy composition is offchain, using the actual truth table of circuit #48; no new circuit is deployed. It changes no score, HUB or settlement.')}</p>`;}
export function updateDecisionLab(game,lang='vi',{container='#decisionLab',example=false}={}){
 let host=document.querySelector(container);if(!host){host=document.createElement('section');host.id=container.slice(1);const anchor=document.querySelector('#financialDashboard')||document.querySelector('main');anchor.after(host);}host.classList.add('decision-lab');if(!game?.started){host.hidden=true;return;}host.hidden=false;
 let p=panels.get(host);if(!p){p={host,index:null,result:null};panels.set(host,p);host.addEventListener('change',e=>{if(e.target.matches('[data-lab-select]')){p.index=Number(e.target.value);p.result=null;draw(p);}});host.addEventListener('click',e=>{const a=e.target.closest('[data-lab]')?.dataset.lab;if(a==='verify')verify(p);if(a==='export')download(p);});}
 p.game=game;p.lang=lang;p.example=example;const key=[game.runId,game.month,game.phase,game.labTrace?.actions?.length,lang,example].join('|');if(p.key!==key){p.key=key;p.result=null;draw(p);}
}
function draw(p){const {host,game:s,lang:l}=p,tr=(a,b)=>t(l,a,b);let candidates=[],error='';try{candidates=choices(s.labTrace);}catch{error='TRACE_UNAVAILABLE';}if(!candidates.some(x=>x.index===p.index))p.index=candidates[0]?.index??null;
 let report;try{if(s.phase==='finished'&&p.index!==null)report=comparison(s,p.index);}catch{error='TRACE_MISMATCH';}
 p.report=report;const current=report?.reference.after||s;
 let html=`<div class="lab-heading"><div><p class="eyebrow">MONEY LAB × TAPEOUT</p><h2>${tr('Nếu chọn khác thì sao?','What if you chose differently?')}</h2></div><span class="lab-badge">${p.example?tr('VÍ DỤ MINH HỌA','ILLUSTRATIVE EXAMPLE'):tr('PHÒNG THÍ NGHIỆM QUYẾT ĐỊNH','DECISION LAB')}</span></div><p>${tr('Thay một lựa chọn, giữ nguyên các lượt gieo và hạt giống sự kiện đã ghi. Khám phá thanh khoản, không sửa kết quả thật.','Change one choice and keep the recorded rolls and event seeds. Explore liquidity without changing your real result.')}</p>`;
 html+=`<p class="lab-fine">${tr('Quy tắc minh họa đang dùng','Illustrative policy in use')}: ${RISK_POLICY.id} · ${s.labTrace?.policy?.id===RISK_POLICY.id?tr('đã ghi trong nhật ký chặng','recorded in the stage trace'):tr('nhật ký cũ chưa ghim phiên bản; đối chiếu theo quy tắc minh họa hiện tại','older trace has no policy pin; the current illustrative policy is used')}</p>`;
 if(s.phase!=='finished')html+=`<p class="lab-fine">${tr('Bộ ghi đang hoạt động từ quyết định đầu tiên được lưu ở bản này. Hoàn thành chặng để thử lựa chọn khác.','Recording begins with the first decision saved in this version. Finish the stage to explore another choice.')}</p>${compact(s,l)}${signalHTML(s,l)}<button data-lab="verify" class="primary">${tr('Đọc TapeOut để kiểm tra quy tắc minh họa','Read TapeOut to check the illustrative policy')}</button>`;
 else if(error||!candidates.length)html+=`<p class="lab-warning">${tr('Chặng này chưa có nhật ký đủ để tái hiện chính xác, hoặc được kết thúc bằng bỏ cuộc. Không dựng lại các sự kiện bị thiếu. Những chặng mới sẽ ghi dữ liệu cần thiết.','This stage lacks an exact replay log or ended through surrender. Missing events will not be reconstructed. New stages record the necessary data.')}</p><a href="./decision-lab.html">${tr('Thử ví dụ minh họa có sẵn →','Try the built-in example →')}</a>`;
 else{
  html+=`<label>${tr('Chọn quyết định muốn nghiên cứu','Choose a decision to explore')}<select data-lab-select>${candidates.map(c=>`<option value="${c.index}" ${c.index===p.index?'selected':''}>${tr('Tháng','Month')} ${c.month} · ${esc(c.title[l])} · ${esc(choiceName(c.original,l))} → ${esc(choiceName(c.alternative,l))}</option>`).join('')}</select></label>`;
  if(report&&!report.alternative.changed)html+=`<p class="lab-warning">${tr('Lựa chọn thay thế không khả thi tại thời điểm đó (vốn hoặc điều kiện dừng). Không tạo kết quả giả cho lựa chọn không thể thực hiện.','The alternative was not feasible then (funds or stop conditions). No result is invented for an impossible choice.')}</p>`;
  else if(report){const a=report.actual,b=report.whatIf;html+=`<div class="lab-comparison-labels"><b>● ${tr('Gốc','Original')}</b><b>┄ ${tr('Thử lại','What if')}</b></div>${timelineSVG(report.baseline.timeline,report.alternative.timeline,l)}<p class="lab-fine">${tr('Đồ thị: tiền mặt + dự phòng. Giữ nguyên sự kiện đã ghi, không mô phỏng các tháng chưa từng được ghi.','Chart: cash + reserve. Recorded events are retained; unrecorded months are not invented.')}</p><div class="lab-table-wrap"><table><thead><tr><th>${tr('Chỉ tiêu','Metric')}</th><th>${tr('Gốc','Original')}</th><th>${tr('Thử lại','What if')}</th></tr></thead><tbody>${[[tr('Tháng quan sát','Observed months'),a.month,b.month],[tr('Tiền mặt + dự phòng','Cash + reserve'),money(a.liquid),money(b.liquid)],[tr('Tài sản ròng','Net worth'),money(a.netWorth),money(b.netWorth)],[tr('Buộc bán tài sản','Forced sales'),a.forcedSales,b.forcedSales],[tr('Khoản thiếu chưa trả','Unpaid shortfall'),money(a.shortfall),money(b.shortfall)]].map(([label,x,y])=>`<tr><th>${label}</th><td>${x}</td><td>${y}</td></tr>`).join('')}</tbody></table></div>`;
   if(report.alternative.stopped)html+=`<p class="lab-warning">${tr('Nhánh thử lại dừng sớm: chặng đã kết thúc hoặc một hành động gốc sau đó không còn thực hiện được. Không tự chọn thay người chơi.','The alternative stops early: the stage ended or a later original action became infeasible. No replacement decision is chosen automatically.')} ${!report.sameHorizon?tr('Hai kết quả có thời hạn khác nhau; không so điểm như hai chặng hoàn chỉnh.','The horizons differ; do not compare their scores as two complete stages.'):''}</p>`;
   html+=`<p>${tr('Một bài học cần kiểm tra','A lesson to examine')}: ${b.shortfall<a.shortfall?tr('Lựa chọn khác giảm khoản thiếu thanh toán trong cùng kịch bản đã ghi.','The alternative reduces unpaid obligations in the recorded scenario.'):b.liquid>a.liquid?tr('Giữ thêm tiền sẵn có có thể tạo khoảng đệm, nhưng cũng thay đổi cơ hội sinh lời.','More available money can create a buffer, while changing investment opportunities.'):b.netWorth>a.netWorth?tr('Tài sản ròng cao hơn cần được đọc cùng số tiền có thể dùng để trả nghĩa vụ.','Higher net worth must be read alongside money available to pay obligations.'):tr('Kết quả thấp hơn vẫn cho thấy cái giá của lựa chọn. Một kịch bản không đủ để kết luận chiến lược luôn tốt hơn.','A lower result still reveals the cost of a choice. One scenario does not establish a superior strategy.')}</p><details><summary>${tr('Đọc toàn bộ số liệu theo tháng','Read all monthly values')}</summary><div class="lab-table-wrap"><table><thead><tr><th>${tr('Tháng','Month')}</th><th>${tr('Thanh khoản gốc','Original liquidity')}</th><th>${tr('Thanh khoản thử lại','Alternative liquidity')}</th></tr></thead><tbody>${[...new Set([...report.baseline.timeline,...report.alternative.timeline].map(x=>x.month))].sort((x,y)=>x-y).map(month=>{const x=report.baseline.timeline.find(p=>p.month===month),y=report.alternative.timeline.find(p=>p.month===month);return `<tr><td>${month}</td><td>${x?money(x.liquid):'—'}</td><td>${y?money(y.liquid):'—'}</td></tr>`;}).join('')}</tbody></table></div></details><div class="lab-policy-grid"><div><h3>${tr('Ngay sau lựa chọn gốc','Immediately after the original choice')}</h3>${compact(current,l)}${signalHTML(current,l)}</div><div><h3>${tr('Ngay sau lựa chọn thay thế','Immediately after the alternative choice')}</h3>${compact(report.alternative.after,l)}${signalHTML(report.alternative.after,l)}</div></div><button data-lab="verify" class="primary">${tr('Đối chiếu hai nhánh bằng mạch TapeOut','Check both branches using TapeOut')}</button>`;
   if(report.choice.proof)html+=`<details><summary>${tr('Bằng chứng NAND đã ghi lúc chơi','NAND receipt captured during play')} · ${report.choice.proof.blockNumber}</summary><pre>${esc(JSON.stringify(report.choice.proof,null,2))}</pre><p class="lab-fine">${tr('Đây là biên nhận cổng dừng gốc, không phải bằng chứng của toàn bộ trò chơi hay nhánh thử lại.','This is the original stop-gate receipt, not proof of the complete game or alternative branch.')}</p></details>`;
  }
 }
 html+=policyCopy(l)+`<div class="lab-proof" role="status" data-lab-proof></div><p class="lab-fine">${tr('Chỉ dùng để học. Không thêm lượt chơi, không cộng/trừ HUB, không thay nhật ký gốc, không ký ví.','Learning only. No new play, HUB changes, original-history edits or wallet signature.')}</p>`;host.innerHTML=html;if(p.result)showProof(p);
}
async function verify(p){const {host,lang:l}=p,key=p.key,target=host.querySelector('[data-lab-proof]'),button=host.querySelector('[data-lab="verify"]');if(!button)return;button.disabled=true;target.textContent=t(l,'Đang đọc mạch #48 trên X Layer mainnet. Không ký ví, không trả gas…','Reading circuit #48 on X Layer mainnet. No wallet signature or gas…');try{const proof=await verifyCircuit(),native=await activeRefProof('0x'+proof.blockNumber.toString(16));if(p.key!==key)return;const states=p.report?.alternative.changed?[p.report.reference.after,p.report.alternative.after]:[p.game];if(states.some(s=>s.phase==='finished')){target.textContent=t(l,'Không áp quy tắc dự phóng sau khi chặng đã kết thúc. Chọn một quyết định trước cuối chặng.','Forecast rules are not applied after stage end. Select an earlier decision.');return;}p.result={proof,nativeProof:native,branches:states.map(s=>composePolicy(policySignals(s),proof)),nativeBranches:native?states.map(s=>nativePolicyResult(policySignals(s),native)):null};showProof(p);}catch{if(p.key===key){p.result=null;target.textContent=t(l,'Chưa đọc được bằng chứng TapeOut. Không gắn nhãn đã xác minh và không dùng kết quả cục bộ thay thế. Có thể thử lại.','TapeOut proof could not be read. No verified label or local substitute is used. You can retry.');}}finally{if(p.key===key)button.disabled=false;}}
function showProof(p){const {lang:l,result:r}=p;if(!r)return;const target=p.host.querySelector('[data-lab-proof]');target.innerHTML=`${r.nativeProof?`<p><b>REF #${r.nativeProof.circuitId}</b> · ${t(l,'Phép ghép R/C/D được đọc trực tiếp từ circuit đã triển khai.','R/C/D combination read directly from the deployed circuit.')}</p>`:''}<strong>${t(l,'Đã đọc bảng chân trị TapeOut','TapeOut truth table read')} · ${t(l,'khối','block')} ${r.proof.blockNumber}</strong><p>${t(l,'Mạch #48 · HashPortAI #167 · mainnet 196. Mỗi nhánh ghép 4 NAND từ các biên nhận cùng khối.','Circuit #48 · HashPortAI #167 · mainnet 196. Each branch composes 4 NAND nodes from same-block receipts.')}</p>${r.branches.map((b,i)=>`<h4>${r.branches.length===1?t(l,'Trạng thái hiện tại','Current state'):i===0?t(l,'Gốc','Original'):t(l,'Thử lại','What if')}: ${b.output===1?t(l,'Đạt ba tiêu chí minh họa','Meets the three illustrative criteria'):t(l,'Chưa đạt ít nhất một tiêu chí','At least one criterion is unmet')}</h4><ol>${b.nodes.map(n=>`<li>${esc(n.name)}: ${n.IN0}, ${n.IN1} → ${n.OUT0}</li>`).join('')}</ol>`).join('')}<details><summary>${t(l,'Đầu vào, calldata và kết quả RPC','Inputs, calldata and RPC results')}</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details><button data-lab="export" class="secondary">${t(l,'Tải bằng chứng JSON','Download JSON evidence')}</button>`;}
function download(p){if(!p.result)return;const payload={schema:'moneylab.decision-policy-export.v1',example:p.example,choice:p.report?.choice||null,comparison:p.report?{actual:p.report.actual,whatIf:p.report.whatIf,sameHorizon:p.report.sameHorizon,stopped:p.report.alternative.stopped}:null,...p.result};const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.href=url;a.download='moneylab-decision-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function mountExample(){const game=exampleGame();updateDecisionLab(game,localStorage.getItem('moneyLabLanguage')==='en'?'en':'vi',{container:'#decisionLab',example:true});}
